{
  "name": "Sutter线性定位器",
  "name_en": "Sutter Linear Positioner",
  "manufacturer": "Sutter Instrument",
  "description": "用于实验中对样品、探针或光学部件进行微步级线性定位的 Sutter 运动装置。该设备支持设备初始化与关闭、命令收发、位置读取、绝对/相对移动以及回零操作。",
  "description_en": "A Sutter motion device used for microstep-resolution linear positioning of samples, probes, or optical components in laboratory experiments. It supports initialization and shutdown, command/reply communication, position readback, absolute/relative moves, and homing.",
  "actions": [
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化设备连接与控制状态。",
      "description_en": "Initialize the device connection and control state."
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "关闭设备连接并停止控制会话。",
      "description_en": "Shut down the device connection and stop the control session."
    },
    {
      "action_name": "auto-sendCommandBytes",
      "description": "向设备发送原始命令字节。",
      "description_en": "Send raw command bytes to the device."
    },
    {
      "action_name": "auto-readReply",
      "description": "读取并按指定格式解析设备回复。",
      "description_en": "Read and decode a device reply using the specified format."
    },
    {
      "action_name": "auto-positionInMicrosteps",
      "description": "以微步为单位获取当前位置。",
      "description_en": "Get the current position in microsteps."
    },
    {
      "action_name": "auto-doGetPosition",
      "description": "获取设备当前位置。",
      "description_en": "Get the current device position."
    },
    {
      "action_name": "auto-doMoveTo",
      "description": "移动到指定位置。",
      "description_en": "Move to a specified position."
    },
    {
      "action_name": "auto-doMoveBy",
      "description": "按给定位移量进行相对移动。",
      "description_en": "Move by a specified relative displacement."
    },
    {
      "action_name": "auto-doHome",
      "description": "执行回零并返回参考原点。",
      "description_en": "Home the device and return to its reference origin."
    },
    {
      "action_name": "auto-work",
      "description": "执行设备工作循环或后台处理。",
      "description_en": "Run the device work cycle or background processing."
    },
    {
      "action_name": "auto-processInputBuffers",
      "description": "处理通信输入缓冲区中的数据。",
      "description_en": "Process data in the communication input buffers."
    }
  ],
  "tag_hints": [
    "linear motion control",
    "microstep positioning",
    "precision translation",
    "device homing",
    "command-reply communication",
    "sample/probe positioning"
  ]
}

